(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.045-t*0.5)*6+Math.cos(y*0.03+t*0.4)*5;
  const w2y = Math.cos(y*0.04+t*0.45)*6+Math.sin(x*0.035-t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.3)*40, 0.11, 2.1],
    [400+Math.cos(t*0.45+2)*70, 200+Math.sin(t*0.65+1)*50, 0.05, 2.8],
    [200+Math.sin(t*0.55+4)*110, 220+Math.cos(t*0.75)*60, 0.09, 1.6]
  ];
  let aS=0, iS=0, i2S=0;
  for (const [sX,sY,f,sp] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    i2S += Math.cos(d*f*0.4-t*sp*0.3+0.8)*0.5;
  }
  const act=aS/9, inh=iS/9, inh2=i2S/9;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+sy*0.05-t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08-ang*5+t*0.9)*0.15;
  const r1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const r2 = Math.tanh((inh2*0.5 + act*0.3 - inh*0.4 + Math.sin(dist*0.06+t)*0.3)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.1;
  const reaction = Math.tanh((r1*0.55+r2*0.25+cell*0.15+micro)*2.5);
  const edge = 1.0-Math.abs(reaction)*0.15+Math.pow(Math.abs(reaction),4)*0.3;
  const lum = 0.75+Math.sin(reaction*Math.PI*1.2)*0.25;
  const v = reaction*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,95],[15,90,120],[20,150,140],[60,185,130],
    [180,200,80],[220,175,55],[215,120,65],[185,65,70],[130,35,80],
    [70,18,60],[20,8,45],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const c0=pal[i], c1=pal[i+1];
  const shift = Math.sin(t*0.15)*8;
  return [
    Math.min(255,Math.max(0,((c0[0]+(c1[0]-c0[0])*f)*lum*edge+shift*0.3)|0)),
    Math.min(255,Math.max(0,((c0[1]+(c1[1]-c0[1])*f)*lum*edge+shift*0.1)|0)),
    Math.min(255,Math.max(0,((c0[2]+(c1[2]-c0[2])*f)*lum*edge-shift*0.2)|0))
  ];
}
